#pragma once
#include "d/t60conv.h"

/*: the bomb's growth answer of the original's one frame. actLive eases
 * mBombScale toward 1 and then (same call) resets it to 0 when the taken bomb is gone (regrow); the original's frame
 * ends at 0 with `growing` from the ease before the reset. On the first step the same ease runs on a copy at dt 1 from
 * the frame-start value; the later steps read the held answer. dt 1: the plain call (no copy, no hold). */
f32 BFlower_addCalc(be<f32>*, f32, f32, f32, f32);
namespace bflowerT60 {
static inline f32 frameGrowing(be<f32>* z) {
    if (!t60c::on())
        return 0.0f; /* unused at dt 1: the step's own ease answers */
    union { f32 f; s32 i; } u;
    u.f = 0.0f;
    if (t60::first_step()) {
        gabi::Local<be<f32>> copy;
        *copy = *z;
        f32 previousDt = t60_set_dt(1.0f);
        u.f = BFlower_addCalc(copy.get(), 1.0f, 0.05f, 0.1f, 0.05f);
        t60_set_dt(previousDt);
    }
    u.i = t60c::heldInt(u.i, 4, z);
    return u.f;
}
}  // namespace bflowerT60
